import React, { useEffect, useState } from "react";
import axios from "axios";
import { useAuth } from "./context/AuthContext";

const API_BASE_URL = process.env.REACT_APP_API_URL || "http://localhost:5000/api";

function App() {
  const { user, login, logout } = useAuth();
  const [candidates, setCandidates] = useState([]);
  const [loading, setLoading] = useState(true);

  // Form States
  const [credentials, setCredentials] = useState({ email: "", password: "" });
  const [formEntry, setFormEntry] = useState({ name: "", position: "", description: "" });

  const fetchCandidates = async () => {
    try {
      setLoading(true);
      const { data } = await axios.get(`${API_BASE_URL}/candidates`);
      setCandidates(data);
    } catch (err) {
      console.error("Failed to fetch candidates", err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchCandidates();
  }, []);

  const handleLogin = async (e) => {
    e.preventDefault();
    try {
      const { data } = await axios.post(`${API_BASE_URL}/auth/login`, credentials);
      login(data.token, data.role);
    } catch (err) {
      alert("Invalid credentials. Please try again.");
    }
  };

  const handleVote = async (id) => {
    try {
      await axios.post(`${API_BASE_URL}/vote/${id}`, {}, {
        headers: { Authorization: `Bearer ${user.token}` }
      });
      fetchCandidates();
    } catch (err) {
      alert(err.response?.data?.message || "Voting failed.");
    }
  };

  return (
    <main className="container">
      <header>
        <h1>Election Portal</h1>
        {user && <button onClick={logout}>Logout ({user.role})</button>}
      </header>

      <hr />

      {!user ? (
        <section className="login-card">
          <h2>Sign In</h2>
          <form onSubmit={handleLogin}>
            <input 
              type="email" 
              placeholder="Email" 
              required
              onChange={(e) => setCredentials({...credentials, email: e.target.value})} 
            />
            <input 
              type="password" 
              placeholder="Password" 
              required
              onChange={(e) => setCredentials({...credentials, password: e.target.value})} 
            />
            <button type="submit">Login</button>
          </form>
        </section>
      ) : (
        user.role === "admin" && (
          <section className="admin-panel">
            <h2>Admin: Add Candidate</h2>
            {/* Form logic for adding candidates here */}
          </section>
        )
      )}

      <section>
        <h2>Current Candidates</h2>
        {loading ? <p>Loading...</p> : (
          <div className="grid">
            {candidates.map((c) => (
              <div key={c._id} className="card">
                <h3>{c.name}</h3>
                <p><strong>{c.position}</strong></p>
                <p>{c.description}</p>
                <div className="stats">
                  <span>Votes: {c.votes}</span>
                  {user?.role === "user" && (
                    <button onClick={() => handleVote(c._id)}>Cast Vote</button>
                  )}
                </div>
              </div>
            ))}
          </div>
        )}
      </section>
    </main>
  );
}

export default App;
